package com.enerlution.ems.business;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.enerlution.ems.auth.AccessControl;
import com.enerlution.ems.common.BusinessException;
import com.enerlution.ems.tenant.TenantContext;
import java.math.BigDecimal;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Dedicated target identity first; all test tables/fixtures and service writes roll back. */
@EnabledIfEnvironmentVariable(named="EMS_TOYINGZHEN_TESTS",matches="true")
class TariffTemplatePostgresTest {
  JdbcTemplate db;AccessControl access;DomainSupport support;TariffTemplateService templates;TariffBindingService bindings;
  DataSourceTransactionManager manager;TransactionStatus outer;Clock clock;LocalDate tomorrow;
  @BeforeEach void setup() throws Exception {
    var ds=new DriverManagerDataSource(required("EMS_TOYINGZHEN_DB_URL"),required("EMS_TOYINGZHEN_DB_USER"),required("EMS_TOYINGZHEN_DB_PASSWORD"));
    manager=new DataSourceTransactionManager(ds);manager.setNestedTransactionAllowed(true);outer=manager.getTransaction(new DefaultTransactionDefinition());db=new JdbcTemplate(ds);
    assertEquals("ems_cloud_saas_toyingzhen",db.queryForObject("SELECT current_database()",String.class));assertEquals("ems_toyingzhen_owner",db.queryForObject("SELECT current_user",String.class));
    clock=Clock.fixed(Instant.now(),ZoneOffset.UTC);tomorrow=LocalDate.now(clock.withZone(ZoneId.of("Asia/Shanghai"))).plusDays(1);
    String schema="tariff_template_test_"+UUID.randomUUID().toString().replace("-","");db.execute("CREATE SCHEMA "+schema);db.execute("SET LOCAL search_path TO "+schema);
    db.execute("""
      CREATE TABLE tenant(id bigint PRIMARY KEY);
      CREATE TABLE app_user(id bigint PRIMARY KEY,tenant_id bigint REFERENCES tenant(id));
      CREATE TABLE station(id bigint PRIMARY KEY,tenant_id bigint REFERENCES tenant(id));
      CREATE TABLE audit_event(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id bigint REFERENCES app_user(id),target_tenant_id bigint REFERENCES tenant(id),action text,detail text);
      CREATE TABLE tariff(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(120) NOT NULL,currency char(3) NOT NULL CHECK(currency ~ '^[A-Z]{3}$'));
      CREATE TABLE tariff_period(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tariff_id bigint NOT NULL REFERENCES tariff(id) ON DELETE CASCADE,start_minute integer NOT NULL CHECK(start_minute>=0),end_minute integer NOT NULL CHECK(end_minute<=1440 AND end_minute>start_minute),band varchar(20) NOT NULL CHECK(band IN ('peak','flat','valley','superPeak')),price_per_kwh numeric(14,6) NOT NULL,EXCLUDE USING gist(tariff_id WITH =,int4range(start_minute,end_minute,'[)') WITH &&));
      CREATE TABLE station_tariff(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,station_id bigint NOT NULL REFERENCES station(id),tariff_id bigint NOT NULL REFERENCES tariff(id),valid_from date NOT NULL,valid_until date NOT NULL CHECK(valid_until>valid_from),EXCLUDE USING gist(station_id WITH =,daterange(valid_from,valid_until,'[)') WITH &&));
      CREATE TABLE settlement_record(id bigint PRIMARY KEY,station_id bigint REFERENCES station(id),statement_amount numeric(18,2));
      INSERT INTO tenant VALUES(11),(22);INSERT INTO app_user VALUES(7,11),(8,11),(9,22);
      INSERT INTO station VALUES(101,11),(102,11),(103,22),(104,11);
      INSERT INTO tariff(id,name,currency) VALUES(501,'Shared legacy','CNY'),(502,'Unbound orphan','USD');
      INSERT INTO tariff_period(tariff_id,start_minute,end_minute,band,price_per_kwh) VALUES(501,0,1440,'flat',-0.123456),(502,0,1440,'flat',9.999999);
      INSERT INTO settlement_record VALUES(1,101,12.34);
      """);
    db.update("INSERT INTO station_tariff(id,station_id,tariff_id,valid_from,valid_until) VALUES(601,104,501,?,?),(602,103,501,?,?),(603,101,501,?,?)",tomorrow.plusDays(30),tomorrow.plusDays(40),tomorrow.plusDays(30),tomorrow.plusDays(40),tomorrow.minusDays(40),tomorrow.minusDays(30));
    db.execute(Files.readString(Path.of("src/main/resources/db/migration/V31__tariff_templates_and_bindings.sql")));
    access=mock(AccessControl.class);actor(7,11);support=new DomainSupport(db,access);templates=new TariffTemplateService(support);bindings=new TariffBindingService(support,clock);
  }
  static String required(String key){return Objects.requireNonNull(System.getenv(key),key+" must be explicitly configured");}
  @AfterEach void cleanup(){if(outer!=null)manager.rollback(outer);}
  void actor(long user,long tenant){when(access.context()).thenReturn(new TenantContext(user,tenant,"enterprise",false));when(access.userId()).thenReturn(user);}
  List<TariffTemplateService.Period> periods(String price){return List.of(new TariffTemplateService.Period(0,1440,"flat",price));}
  TariffTemplateService.Template create(String name,String price){return templates.create(new TariffTemplateService.CreateRequest(name,"CNY","fixed",periods(price)));}
  UUID id(TariffTemplateService.Template template){return UUID.fromString(template.id());}
  TariffBindingService.Binding bind(long station,TariffTemplateService.Template template,LocalDate from,LocalDate until){return bindings.create(station,new TariffBindingService.CreateRequest(id(template),template.version(),from,until));}
  void failure(int status,Runnable call){var savepoint=manager.getTransaction(new DefaultTransactionDefinition(TransactionDefinition.PROPAGATION_NESTED));try{assertEquals(status,assertThrows(BusinessException.class,call::run).status());}finally{manager.rollback(savepoint);}}
  void constraint(Runnable call){var savepoint=manager.getTransaction(new DefaultTransactionDefinition(TransactionDefinition.PROPAGATION_NESTED));try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,call::run);}finally{manager.rollback(savepoint);}}
  @Test void legacyBindingsAndOrphansStayReadableWithoutGuessedTemplateOwnershipOrGetWrites(){
    int audits=db.queryForObject("SELECT count(*) FROM audit_event",Integer.class);assertTrue(templates.list().isEmpty());
    var legacy=bindings.list(104,true).getFirst();assertNull(legacy.templateId());assertNull(legacy.templateVersion());assertNull(legacy.pricingMode());assertEquals("-0.123456",legacy.periods().getFirst().pricePerKwh());assertTrue(legacy.modifiable());
    assertFalse(bindings.list(101,true).getFirst().modifiable());assertEquals(1,bindings.history(104,601).size());assertEquals(audits,db.queryForObject("SELECT count(*) FROM audit_event",Integer.class));
    assertEquals(3,db.queryForObject("SELECT count(*) FROM station_tariff_history",Integer.class));
    assertEquals(2,db.queryForObject("SELECT count(*) FROM tariff",Integer.class));
  }
  @Test void templateVersionsNamesArchivalAndSharedTenantLibraryRemainDurable(){
    var first=create(" Solar ","-12.345678");assertEquals("Solar",first.name());assertEquals("-12.345678",first.periods().getFirst().pricePerKwh());
    failure(409,()->create("solar","1"));
    var updated=templates.update(id(first),new TariffTemplateService.UpdateRequest("Renamed","USD","fixed",periods("0"),1L));assertEquals(2,updated.version());assertEquals("0.000000",updated.periods().getFirst().pricePerKwh());
    assertEquals(updated,new TariffTemplateService(support).get(id(first)));assertEquals(2,db.queryForObject("SELECT count(*) FROM tariff_template_version",Integer.class));
    failure(409,()->templates.update(id(first),new TariffTemplateService.UpdateRequest("Stale","CNY","fixed",periods("1"),1L)));failure(409,()->templates.archive(id(first),1L));
    actor(8,11);assertEquals(updated,templates.get(id(first)));actor(9,22);assertTrue(templates.list().isEmpty());failure(404,()->templates.get(id(first)));actor(7,11);
    templates.archive(id(first),2L);assertTrue(templates.list().isEmpty());failure(404,()->templates.get(id(first)));failure(409,()->bind(101,updated,tomorrow,tomorrow.plusDays(1)));
    assertEquals("Renamed",create("Renamed","1").name());
  }
  @Test void bindingSnapshotsSurviveTemplateUpdatesArchivalAndHistoryPreservesEveryFutureDateState(){
    var template=create("Original","-0.000001");var first=bind(101,template,tomorrow,tomorrow.plusDays(1));assertTrue(first.modifiable());assertEquals(1,first.templateVersion());
    var revised=templates.update(id(template),new TariffTemplateService.UpdateRequest("New name","USD","fixed",periods("99.123456"),1L));
    var still=bindings.list(101,false).stream().filter(b->b.id().equals(first.id())).findFirst().orElseThrow();assertEquals(first,still);assertEquals("Original",still.name());assertEquals("CNY",still.currency());assertEquals("-0.000001",still.periods().getFirst().pricePerKwh());
    var second=bind(102,revised,tomorrow,tomorrow.plusDays(1));assertEquals(2,second.templateVersion());assertEquals("99.123456",second.periods().getFirst().pricePerKwh());
    long bindingId=Long.parseLong(first.id());var moved=bindings.update(101,bindingId,new TariffBindingService.UpdateRequest(tomorrow.plusDays(2),tomorrow.plusDays(3),1L));assertEquals(2,moved.version());
    failure(409,()->bindings.update(101,bindingId,new TariffBindingService.UpdateRequest(tomorrow.plusDays(4),tomorrow.plusDays(5),1L)));
    templates.archive(id(template),2L);bindings.unbind(101,bindingId,2L);
    assertTrue(bindings.list(101,false).stream().noneMatch(b->b.id().equals(first.id())));
    var inactive=bindings.list(101,true).stream().filter(b->b.id().equals(first.id())).findFirst().orElseThrow();assertFalse(inactive.active());assertFalse(inactive.modifiable());
    var history=bindings.history(101,bindingId);assertEquals(List.of(1L,2L,3L),history.stream().map(TariffBindingService.Binding::version).toList());assertEquals(tomorrow,history.getFirst().validFrom());assertTrue(history.getFirst().active());assertFalse(history.getLast().active());assertTrue(history.stream().noneMatch(TariffBindingService.Binding::modifiable));
    assertEquals(new BigDecimal("12.34"),db.queryForObject("SELECT statement_amount FROM settlement_record WHERE id=1",BigDecimal.class));
  }
  @Test void overlapsCrossTenantStaleTemplateVersionAndHistoricalChangesAreRejectedAtomically(){
    var own=create("A","1");bind(101,own,tomorrow,tomorrow.plusDays(3));
    failure(409,()->bind(101,own,tomorrow.plusDays(1),tomorrow.plusDays(4)));bind(101,own,tomorrow.plusDays(3),tomorrow.plusDays(4));
    failure(403,()->bind(103,own,tomorrow,tomorrow.plusDays(1)));
    failure(409,()->bindings.create(102,new TariffBindingService.CreateRequest(id(own),2L,tomorrow,tomorrow.plusDays(1))));
    actor(9,22);failure(404,()->bind(103,own,tomorrow,tomorrow.plusDays(1)));actor(7,11);
    failure(400,()->bind(102,own,tomorrow.minusDays(1),tomorrow));
    failure(409,()->bindings.update(101,603,new TariffBindingService.UpdateRequest(tomorrow.plusDays(20),tomorrow.plusDays(21),1L)));failure(409,()->bindings.unbind(101,603,1L));
    assertEquals(5,db.queryForObject("SELECT count(*) FROM station_tariff",Integer.class));assertEquals(5,db.queryForObject("SELECT count(*) FROM station_tariff_history",Integer.class));
    doThrow(new BusinessException(403,"revoked")).when(access).requireStationPermission(101,"tariff.manage");failure(403,()->bindings.list(101,true));failure(403,()->bindings.history(101,603));
  }
  @Test void futureLegacyChangesAndOldCreateGetRemainCompatibleWithActiveFiltering(){
    bindings.update(104,601,new TariffBindingService.UpdateRequest(tomorrow.plusDays(41),tomorrow.plusDays(42),1L));bindings.unbind(104,601,2L);
    assertEquals(3,bindings.history(104,601).size());assertNull(bindings.history(104,601).getFirst().templateId());
    var old=new OperationsController(support);assertTrue(((List<?>)old.tariffs(104).data()).isEmpty());
    old.tariff(new OperationsController.Tariff(104,"Old API created","CNY",tomorrow,tomorrow.plusDays(1),List.of(new OperationsController.TariffPeriod(0,1440,"flat",new BigDecimal("1.234567")))));
    assertEquals(1,((List<?>)old.tariffs(104).data()).size());var legacy=bindings.list(104,false).getFirst();assertNull(legacy.templateId());assertEquals("1.234567",legacy.periods().getFirst().pricePerKwh());assertTrue(templates.list().isEmpty());
  }
  @Test void databaseGuardsFreezePublishedCarrierPeriodsBindingIdentityAndHistory(){
    var template=create("A","1");var binding=bind(101,template,tomorrow,tomorrow.plusDays(1));
    long tariff=db.queryForObject("SELECT tariff_id FROM tariff_template_version WHERE template_id=? AND version=1",Long.class,id(template));
    constraint(()->db.update("UPDATE tariff SET name='Mutated' WHERE id=?",tariff));constraint(()->db.update("UPDATE tariff_period SET price_per_kwh=3 WHERE tariff_id=?",tariff));
    constraint(()->db.update("INSERT INTO tariff_period(tariff_id,start_minute,end_minute,band,price_per_kwh) VALUES(?,0,1,'flat',1)",tariff));
    constraint(()->db.update("UPDATE tariff_period SET tariff_id=? WHERE tariff_id=502",tariff));
    constraint(()->db.update("UPDATE tariff_template_version SET pricing_mode='tou' WHERE template_id=?",id(template)));
    constraint(()->db.update("UPDATE station_tariff SET tariff_id=502,version=version+1 WHERE id=?",Long.parseLong(binding.id())));
    constraint(()->db.update("DELETE FROM station_tariff WHERE id=?",Long.parseLong(binding.id())));
    constraint(()->db.update("UPDATE station_tariff_history SET name='Mutated' WHERE binding_id=?",Long.parseLong(binding.id())));
    constraint(()->db.update("UPDATE tariff_period SET price_per_kwh=1 WHERE tariff_id=501"));
    assertEquals("1.000000",bindings.list(101,false).stream().filter(b->b.id().equals(binding.id())).findFirst().orElseThrow().periods().getFirst().pricePerKwh());
  }
  @Test void databaseRejectsTodayTemplateBindingButKeepsNullTemplateLegacyInsertCompatible(){
    var template=create("Future only","1");
    long tariff=db.queryForObject("SELECT tariff_id FROM tariff_template_version WHERE template_id=? AND version=1",Long.class,id(template));
    LocalDate today=tomorrow.minusDays(1);
    constraint(()->db.update("INSERT INTO station_tariff(station_id,tariff_id,template_id,template_version,valid_from,valid_until) VALUES(102,?,?,1,?,?)",tariff,id(template),today,tomorrow));
    assertTrue(bindings.list(102,true).isEmpty());
    var old=new OperationsController(support);
    old.tariff(new OperationsController.Tariff(102,"Legacy date compatibility","CNY",today,tomorrow,List.of(new OperationsController.TariffPeriod(0,1440,"flat",new BigDecimal("1.234567")))));
    var legacy=bindings.list(102,false).getFirst();assertNull(legacy.templateId());assertFalse(legacy.modifiable());
    assertEquals("1.234567",legacy.periods().getFirst().pricePerKwh());
  }
  @ParameterizedTest @ValueSource(strings={"create","update","archive","bind","dates","unbind"})
  void eachMutationIsRollbackOnlyWhenAuditFailsBeforeFixtureCleanup(String operation){
    var template=create("A","1");var binding=bind(101,template,tomorrow,tomorrow.plusDays(1));
    long raw=db.queryForObject("SELECT count(*) FROM tariff",Long.class),history=db.queryForObject("SELECT count(*) FROM station_tariff_history",Long.class);
    var failingSupport=new DomainSupport(db,access){@Override public void audit(String action,Map<String,?> detail){throw new BusinessException(503,"audit unavailable");}@Override public void auditStation(String action,long station,Object detail){throw new BusinessException(503,"audit unavailable");}};
    var failingTemplates=new TariffTemplateService(failingSupport);var failingBindings=new TariffBindingService(failingSupport,clock);assertFalse(outer.isRollbackOnly());
    var savepoint=manager.getTransaction(new DefaultTransactionDefinition(TransactionDefinition.PROPAGATION_NESTED));
    try{
      Runnable call=switch(operation){case "create"->()->failingTemplates.create(new TariffTemplateService.CreateRequest("B","CNY","fixed",periods("2")));case "update"->()->failingTemplates.update(id(template),new TariffTemplateService.UpdateRequest("B","USD","fixed",periods("2"),1L));case "archive"->()->failingTemplates.archive(id(template),1L);case "bind"->()->failingBindings.create(102,new TariffBindingService.CreateRequest(id(template),1L,tomorrow,tomorrow.plusDays(1)));case "dates"->()->failingBindings.update(101,Long.parseLong(binding.id()),new TariffBindingService.UpdateRequest(tomorrow.plusDays(2),tomorrow.plusDays(3),1L));default->()->failingBindings.unbind(101,Long.parseLong(binding.id()),1L);};
      assertEquals(503,assertThrows(BusinessException.class,call::run).status());assertTrue(outer.isRollbackOnly());
    }finally{manager.rollback(savepoint);}
    assertEquals(raw,db.queryForObject("SELECT count(*) FROM tariff",Long.class));assertEquals(history,db.queryForObject("SELECT count(*) FROM station_tariff_history",Long.class));assertEquals(template,templates.get(id(template)));assertEquals(binding,bindings.list(101,false).stream().filter(b->b.id().equals(binding.id())).findFirst().orElseThrow());
  }
}
